from pathlib import Path
R=Path(__file__).resolve().parent.parent
nav=[('index.html','Home'),('vision.html','The vision'),('lodges.html','Private lodges'),('living.html','Mountain living'),('land.html','The land')]
def link(url,label):return f'<a class="text-link" href="{url}">{label} <span aria-hidden="true">↗</span></a>'
def pic(name,alt,caption='Architectural concept · Mount Paradise',cls=''):
 return f'<figure class="{cls}"><a href="assets/{name}.jpg" data-lightbox aria-label="Enlarge: {alt}"><img src="assets/{name}.jpg" alt="{alt}" loading="lazy" width="1536" height="1024"></a><figcaption>{caption}<span>View artwork ↗</span></figcaption></figure>'
def intro(k,title,text):return f'<section class="section intro"><p class="eyebrow">{k}</p><div class="split"><h2>{title}</h2><div class="prose"><p>{text}</p></div></div></section>'
def hero(img,k,title,desc,home=False):return f'<section class="hero {"home" if home else "subhero"}"><img class="hero-image" src="assets/{img}.jpg" alt="Mount Paradise stone and timber mountain lodge concept" fetchpriority="high"><div class="hero-shade"></div><div class="hero-content"><p class="eyebrow">{k}</p><h1>{title}</h1><p class="hero-description">{desc}</p>{link("lodges.html" if home else "#discover","Explore private lodges" if home else "Discover more")}</div><div class="hero-bottom"><span>Trawas · East Java · Indonesia</span><span>Proposed design · Artist’s impression</span></div></section>'
def row(num,title,text):return f'<article class="principle"><span class="eyebrow">{num}</span><h3>{title}</h3><p>{text}</p></article>'
footer='''<footer><div class="footer-top"><p class="eyebrow">Mount Paradise · Trawas</p><h2>A little closer<br>to paradise.</h2><a class="text-link" href="vision.html">Discover the vision ↗</a></div><div class="footer-bottom"><span>© 2026 Mount Paradise</span><span>A mountain community in the making.</span><a href="#top">Back to top ↑</a></div><p class="disclosure">An early development vision. Renderings are proposed concepts, not completed residences or guaranteed views. Layouts, amenities and areas remain subject to site studies, design development and approvals.</p></footer>'''
pages={}
pages['index.html']=('A different altitude of living',hero('signature-lodge','A private mountain sanctuary','Life at a<br><em>different altitude.</em>','Stone, timber, gardens and the quiet luxury of the mountains.',True)+intro('01 / The spirit of the place','Room to breathe.<br>Space to belong.','In the green highlands of Trawas, Mount Paradise imagines a more considered way of living. Private lodges open onto generous gardens. Mornings begin on the terrace. Evenings bring everyone a little closer.')+f'<section class="section feature dark" id="discover"><div>{pic("interior","Warm timber and volcanic stone living room opening to a mountain garden")}</div><div class="feature-copy"><p class="eyebrow">02 / The private lodge</p><h2>Grounded in stone.<br>Warmed by timber.</h2><p>Homes shaped around the simple pleasure of being here: deep verandas, tactile interiors, a private pool and a garden made for long afternoons.</p>{link("lodges.html","Explore the collection")}</div></section>'+f'<section class="section"><div class="section-heading"><div><p class="eyebrow">03 / A day in paradise</p><h2>Time, beautifully spent.</h2></div>{link("living.html","The mountain lifestyle")}</div>{pic("evening","Friends sharing guitar music beside a garden pond and fire lounge")}<div class="thirds">{row("Morning","The first cup","Coffee on the veranda. Tea with a view. A slow beginning, with the garden waking around you.")}{row("Afternoon","Outside, together","A swim, a garden lunch, a walk beneath the trees. Everyday pleasures with room to linger.")}{row("Evening","Follow the firelight","A guitar beside the pond, lanterns in the leaves and conversations that carry into the night.")}</div></section>'+f'<section class="section plan-preview"><div class="split"><div><p class="eyebrow">04 / The landscape vision</p><h2>A community.<br>Within a garden.</h2></div><div><p>An initial area of approximately 8–10 hectares, with a further 20+ hectares offering a future expansion opportunity.</p>{link("land.html","Explore the land")}</div></div>{pic("masterplan","Watercolor vision of lodges and gardens arranged around a central pond","Conceptual landscape study · Not a surveyed master plan")}</section>')
pages['vision.html']=('The vision',hero('signature-lodge','The vision','A place to live<br><em>more fully.</em>','Luxury measured in space, stillness and a deeper connection to nature.')+f'<div id="discover">{intro("Our point of departure","A real place.<br>A distinctive spirit.","Mount Paradise begins with an existing stone villa in Trawas. Its sheltered terraces, substantial timber, natural stone and abundant planting give the project its architectural language. The ambition is to extend that sense of belonging into an intimate mountain community.")}</div><section class="section artwork">{pic("original-watercolor","Original Mount Paradise watercolor showing stone lodge, mountain landscape and the luxury mountain residences identity","The original watercolor vision · Concept artwork")}</section><section class="section feature"><div>{pic("original-veranda","The existing model villa veranda with stone walls timber beams and garden planting","Original model villa · User-supplied reference photograph")}</div><div class="feature-copy"><p class="eyebrow">From the model villa</p><h2>Let the materials<br>tell the story.</h2><p>Stone with texture. Timber with warmth. Generous shelter from the rain. These details give the architecture its character and guide the new lodge studies.</p><p>Layered horticulture belongs at the heart of the design, softening the edges between home and landscape.</p></div></section><section class="section dark"><p class="eyebrow">The guiding principles</p><h2>Less hurry.<br>More life.</h2><div class="thirds">{row("01","Nature, every day","Planting, paths and outdoor rooms bring the landscape into daily routines.")}{row("02","Wellbeing by design","Space to walk, rest, swim and share nourishing meals. Clean water and thoughtful environmental design are priorities for the next planning stage.")}{row("03","Privacy & belonging","A private home with its own garden, alongside inviting places to meet neighbors and gather with friends.")}</div></section>')
pages['lodges.html']=('Private lodges',hero('vista','The private lodge collection','Your own corner<br><em>of the mountain.</em>','Early design studies in stone, timber and garden living.')+f'<div id="discover">{intro("Architecture with a sense of place","Open to the view.<br>Rooted in the garden.","Each lodge begins with a private outdoor world: a covered terrace, a pool, lush planting and a place to cook and gather. Three design directions explore different ways of living in the landscape.")}</div><section class="section lodge-list"><article class="lodge-row">{pic("signature-lodge","Signature stone lodge with pool and lush mountain garden")}<div><p class="eyebrow">Study 01 / The Garden Lodge</p><h2>Living in<br>the green.</h2><p>A sheltered veranda connects relaxed living spaces to a private pool and layered garden. A proposed BBQ dining terrace makes entertaining part of everyday life.</p>{link("garden-lodge.html","Explore this lodge")}</div></article><article class="lodge-row">{pic("vista","Vista lodge concept facing green volcanic mountains")}<div><p class="eyebrow">Study 02 / The Vista Lodge</p><h2>A front row<br>to the mountains.</h2><p>A broader terrace and generous glazing frame the landscape. Long pool edges, shaded seating and warm interior spaces create a home for unhurried gatherings.</p><p class="note">Exterior study · Layout and dimensions in development.</p></div></article><article class="lodge-row">{pic("interior","Interior material study for a secluded forest lodge","Interior concept · Shared material palette")}<div><p class="eyebrow">Study 03 / The Forest Lodge</p><h2>A quieter<br>kind of retreat.</h2><p>An intimate design direction for homes among trees: warm timber interiors, garden-facing rooms, a private plunge pool and a covered reading veranda.</p><p class="note">Design brief · Exterior and floor plan to be developed.</p></div></article></section>')
pages['garden-lodge.html']=('The Garden Lodge',hero('signature-lodge','Private lodges / Study 01','The Garden<br><em>Lodge.</em>','A home that unfolds into its own private landscape.')+f'<div id="discover">{intro("An early architectural study","The garden is<br>another room.","The Garden Lodge explores a close relationship between indoor comfort and outdoor living. Stone columns and timber beams frame the veranda, while generous doors connect the lounge to the pool and planting beyond.")}</div><section class="section">{pic("interior","Lodge living room with natural materials and open garden doors","Interior direction · Indicative study")}<div class="thirds">{row("01","The covered veranda","A deeply sheltered outdoor living room for morning coffee, afternoon tea and the sound of rain.")}{row("02","Pool & garden","A private swimming space edged with stone, flowering plants and places to rest in the shade.")}{row("03","Dining outdoors","A proposed private BBQ area and generous dining table, set apart from quiet corners of the garden.")}</div></section><section class="section dark"><div class="split"><h2>Beautiful details.<br>Every day.</h2><div><p>The material direction draws directly from the existing villa: dark stone, substantial timber, warm lanterns, textured fabrics and handmade furniture.</p><p>Floor plans, room counts, dimensions and specifications will be established through architectural and site studies.</p>{link("lodges.html","Return to all lodges")}</div></div></section>')
pages['living.html']=('Mountain living',hero('evening','The mountain lifestyle','The days you<br><em>wish would last.</em>','Coffee, gardens, water and good company. A different rhythm of life.')+f'<div id="discover">{intro("A day, imagined","Nothing hurried.<br>Everything felt.","The luxury of Mount Paradise is in the everyday. A warm cup in the cool morning air. Space to wander through the garden. An evening that becomes a story you tell again.")}</div><section class="section feature">{pic("interior","Tea and coffee in a warm lodge living room overlooking the garden")}<div class="feature-copy"><p class="eyebrow">07:00 / A slow beginning</p><h2>Start with<br>the view.</h2><p>Make coffee. Steep a pot of tea. Take your favorite seat on the terrace and watch the light move through the leaves.</p><p>Gardens for walking, quiet corners for reading and room to stretch bring a gentler rhythm to the morning.</p></div></section><section class="section feature dark"><div class="feature-copy"><p class="eyebrow">13:00 / Life outdoors</p><h2>A table.<br>A pool.<br>A whole afternoon.</h2><p>Lunch becomes a gathering at your own BBQ terrace. A swim becomes an hour beside the water. Friends stay a little longer.</p><p>The landscape vision includes paths, tea gardens and places to pause, with the scale and planting to be developed through site studies.</p></div>{pic("signature-lodge","Private lodge pool and sheltered outdoor gathering terrace")}</section><section class="section"><p class="eyebrow">18:30 / The glow of evening</p><h2>One more song.<br>One more story.</h2>{pic("evening","Guitar music and warm firelight beside a lush garden pond")}<div class="split"><p>Lanterns glow among the trees. A guitar finds its way into the circle. Firelight dances on stone as the mountain fades into the evening.</p><p>A pondside gathering place and carefully designed fire lounge are part of the proposed community experience: intimate, comfortable and surrounded by nature.</p></div></section>')
pages['land.html']=('The land & development vision','<section class="page-heading"><p class="eyebrow">The land / Trawas, East Java</p><h1>A landscape<br>of <em>possibility.</em></h1><p>An intimate first chapter. Room for a thoughtful future.</p></section>'+f'<section class="section artwork" id="discover">{pic("masterplan","Illustrative watercolor neighborhood with individual lodges footpaths gardens and pond","Landscape vision · Illustrative arrangement, not a site survey")}</section><section class="section"><div class="split"><div><p class="eyebrow">01 / The first chapter</p><h2>8–10 <em>hectares.</em></h2><p>The approximate initial development area identified for the Mount Paradise vision. Private lodges, garden paths and modest shared gathering places establish the character of the community.</p></div><div><p class="eyebrow">02 / Future possibility</p><h2>20+ <em>hectares.</em></h2><p>A further expansion opportunity allows the community to evolve over time. The later phase can respond to what is learned from the first, alongside future site assessment and approvals.</p></div></div></section><section class="section dark"><p class="eyebrow">A landscape first approach</p><h2>Give nature<br>the space it deserves.</h2><div class="thirds">{row("01","Follow the land","Study topography, access and natural drainage before establishing roads, home sites or final boundaries.")}{row("02","Plant for belonging","Explore layered highland gardens, shaded walking routes and a pondside common landscape.")}{row("03","Build thoughtfully","Develop water, wastewater, infrastructure and environmental plans alongside the architecture, at a scale suited to the site.")}</div></section><section class="section"><div class="split"><h2>A vision taking shape.</h2><div><p>This watercolor communicates atmosphere and design intent. It does not prescribe plot counts, boundaries, orientation or development density.</p><p>The next design stage will bring land surveys, infrastructure studies and detailed architecture together.</p>{link("vision.html","Return to the vision")}</div></div></section>')
for file,(title,body) in pages.items():
 active='aria-current="page"'
 navhtml=''.join(f'<a href="{u}" {active if u==file else ""}>{label}</a>' for u,label in nav)
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Mount Paradise, Trawas</title><meta name="description" content="Explore Mount Paradise: a vision for private stone and timber mountain lodges, lush gardens and thoughtful living in Trawas, East Java."><meta name="theme-color" content="#20362d"><meta property="og:title" content="{title} | Mount Paradise"><meta property="og:description" content="A private mountain sanctuary in Trawas. Explore the architecture, gardens and vision."><meta property="og:type" content="website"><meta property="og:image" content="https://civnexus.github.io/langit/assets/signature-lodge.jpg"><meta property="og:url" content="https://civnexus.github.io/langit/{file}"><meta name="twitter:card" content="summary_large_image"><link rel="canonical" href="https://civnexus.github.io/langit/{file}"><link rel="icon" href="assets/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="styles.css"><script src="site.js" defer></script></head><body id="top" class="{"land-page" if file=="land.html" else ""}"><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="index.html" aria-label="Mount Paradise home"><svg viewBox="0 0 80 34" aria-hidden="true"><path d="M3 31 29 4 43 21 53 10 77 31M17 25 29 16 37 21"/></svg><span>MOUNT PARADISE<small>T R A W A S</small></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu <span>☰</span></button><nav id="navigation" aria-label="Main navigation">{navhtml}</nav></header><main id="main">{body}</main>{footer}<dialog class="lightbox"><button aria-label="Close artwork" class="close-lightbox">Close ×</button><img alt=""><p></p></dialog></body></html>'''
 (R/file).write_text(html)
(R/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>https://civnexus.github.io/langit/{f}</loc></url>' for f in pages)+'</urlset>')
print(f'Built {len(pages)} pages')
